private ArrayList<TimeBarInfo> convertDayBeanToTimeBarInfoList(AlarmTimeGetJsonParse.DayBean dayBean) {
    ArrayList<TimeBarInfo> arrayList = new ArrayList<>();
    for (AlarmTimeGetJsonParse.DayBean.ScheBean scheBean : dayBean.getSche()) {
        LocalTime localTime = LocalTime.parse(scheBean.getS_time());
        LocalTime localTime2 = LocalTime.parse(scheBean.getE_time());
        int iDayBeanModeToTimeBarInfo = TimeBarInfo.dayBeanModeToTimeBarInfo(scheBean.getMode());
        if (localTime2.isEqual(new LocalTime(23, 59, 59))) {
            localTime2 = TimeBarInfo.lastTimeInDay;
        }
        arrayList.add(new TimeBarInfo(localTime, localTime2, iDayBeanModeToTimeBarInfo));
    }
    return arrayList;
}
